add("it5.q1", ("निम्नलिखित को पार्श्वक्रम में संयोजित करने पर तुल्य प्रतिरोध का निर्णय कीजिए: (a) 1 Ω तथा 10⁶ Ω, (b) 1 Ω, 10³ Ω तथा 10⁶ Ω।", "નીચેનાંને સમાંતર જોડતાં સમતુલ્ય અવરોધનો અંદાજ આપો: (a) 1 Ω અને 10⁶ Ω, (b) 1 Ω, 10³ Ω અને 10⁶ Ω."),
    {0: ("पार्श्वक्रम में तुल्य प्रतिरोध सबसे छोटे प्रतिरोध से कम होता है।", "સમાંતર જોડાણમાં સમતુલ્ય અવરોધ સૌથી નાના અવરોધ કરતાં ઓછો હોય છે."), 1: ("(a) 1 Ω से थोड़ा कम (लगभग 0.999999 Ω)। (b) यह भी 1 Ω से थोड़ा कम (लगभग 0.999 Ω)।", "(a) 1 Ω કરતાં થોડો ઓછો (આશરે 0.999999 Ω). (b) આ પણ 1 Ω કરતાં થોડો ઓછો (આશરે 0.999 Ω).")})
add("it5.q2", ("100 Ω का एक विद्युत लैंप, 50 Ω का एक विद्युत टोस्टर तथा 500 Ω का एक जल फ़िल्टर 220 V के विद्युत स्रोत से पार्श्वक्रम में संयोजित हैं। उस विद्युत इस्तरी का प्रतिरोध क्या है जिसे यदि समान स्रोत के साथ संयोजित कर दें तो वह उतनी ही विद्युत धारा लेती है जितनी तीनों युक्तियाँ लेती हैं। यह भी ज्ञात कीजिए कि इस विद्युत इस्तरी से कितनी विद्युत धारा प्रवाहित होती है?",
               "100 Ω નો વિદ્યુત-લૅમ્પ, 50 Ω નું ટોસ્ટર અને 500 Ω નું વૉટર-ફિલ્ટર 220 V ના સ્રોત સાથે સમાંતર જોડ્યાં છે. એવી ઇસ્ત્રીનો અવરોધ કેટલો છે જે આ જ સ્રોત સાથે જોડતાં ત્રણેય સાધનો જેટલો પ્રવાહ લે? આ ઇસ્ત્રીમાંથી કેટલો પ્રવાહ વહે છે?"))
add("it5.q3", ("बैटरी के साथ श्रेणीक्रम में संयोजित करने की अपेक्षा वैद्युत युक्तियों को पार्श्वक्रम में संयोजित करने के क्या लाभ हैं?", "બૅટરી સાથે શ્રેણીમાં જોડવાને બદલે વિદ્યુત-સાધનોને સમાંતર જોડવાના શા ફાયદા છે?"),
    {0: ("हर युक्ति को पूरी वोल्टता मिलती है और वह अपनी आवश्यक धारा लेती है; एक युक्ति ख़राब होने पर भी बाकी काम करती रहती हैं।", "દરેક સાધનને પૂરો વૉલ્ટેજ મળે છે અને તે પોતાને જોઈતો પ્રવાહ લે છે; એક સાધન બગડે તો પણ બાકીનાં કામ કરતાં રહે છે."),
     1: ("हर युक्ति को स्वतंत्र रूप से चालू या बंद किया जा सकता है, और परिपथ का कुल प्रतिरोध कम होता है।", "દરેક સાધનને સ્વતંત્ર રીતે ચાલુ કે બંધ કરી શકાય છે, અને પરિપથનો કુલ અવરોધ ઓછો હોય છે.")})
add("it5.q4", ("2 Ω, 3 Ω तथा 6 Ω के तीन प्रतिरोधकों को किस प्रकार संयोजित करेंगे कि संयोजन का कुल प्रतिरोध (a) 4 Ω, (b) 1 Ω हो?", "2 Ω, 3 Ω અને 6 Ω ના ત્રણ અવરોધકોને કેવી રીતે જોડશો કે જોડાણનો કુલ અવરોધ (a) 4 Ω, (b) 1 Ω થાય?"),
    {0: ("(a) 3 Ω और 6 Ω पार्श्वक्रम में ({0} Ω), 2 Ω के साथ श्रेणीक्रम में: {1} Ω", "(a) 3 Ω અને 6 Ω સમાંતર ({0} Ω), 2 Ω સાથે શ્રેણીમાં: {1} Ω"), 1: ("(b) तीनों पार्श्वक्रम में: {0}, अतः {1} Ω", "(b) ત્રણેય સમાંતર: {0}, તેથી {1} Ω")})
add("it5.q5", ("4 Ω, 8 Ω, 12 Ω तथा 24 Ω प्रतिरोध की कुंडलियों को किस प्रकार संयोजित करें कि संयोजन से (a) अधिकतम, (b) निम्नतम प्रतिरोध प्राप्त हो सके?", "4 Ω, 8 Ω, 12 Ω અને 24 Ω ના ગૂંચળાંને કેવી રીતે જોડવાં કે જોડાણથી (a) મહત્તમ, (b) લઘુતમ અવરોધ મળે?"),
    {0: ("(a) अधिकतम, सभी श्रेणीक्रम में: {0} Ω", "(a) મહત્તમ, બધાં શ્રેણીમાં: {0} Ω"), 1: ("(b) निम्नतम, सभी पार्श्वक्रम में: {0}, अतः {1} Ω", "(b) લઘુતમ, બધાં સમાંતર: {0}, તેથી {1} Ω")})
add("it6.q1", ("किसी विद्युत हीटर की डोरी क्यों उत्तप्त नहीं होती जबकि उसका तापन अवयव उत्तप्त हो जाता है?", "વિદ્યુત-હીટરની દોરી કેમ ગરમ થતી નથી જ્યારે તેનો તાપક ભાગ ગરમ થઈ જાય છે?"),
    {0: ("डोरी और तापन अवयव में एक ही धारा बहती है, और उत्पन्न ऊष्मा {0} है।", "દોરી અને તાપક ભાગમાં એક જ પ્રવાહ વહે છે, અને ઉત્પન્ન ઉષ્મા {0} છે."), 1: ("अवयव का प्रतिरोध अधिक है, इसलिए वह बहुत गर्म होकर चमकता है; ताँबे की डोरी का प्रतिरोध बहुत कम है और वह ठंडी रहती है।", "તાપક ભાગનો અવરોધ વધુ છે, તેથી તે ખૂબ ગરમ થઈ પ્રકાશે છે; તાંબાની દોરીનો અવરોધ ખૂબ ઓછો છે અને તે ઠંડી રહે છે.")})
add("it6.q2", ("एक घंटे में 50 V विभवांतर से 96000 कूलॉम आवेश को स्थानांतरित करने में उत्पन्न ऊष्मा परिकलित कीजिए।", "એક કલાકમાં 50 V સ્થિતિમાનના તફાવતથી 96000 કુલંબ વિદ્યુતભાર સ્થાનાંતરિત કરવામાં ઉત્પન્ન ઉષ્મા ગણો."))
add("it6.q3", ("20 Ω प्रतिरोध की कोई विद्युत इस्तरी 5 A विद्युत धारा लेती है। 30 s में उत्पन्न ऊष्मा परिकलित कीजिए।", "20 Ω અવરોધની વિદ્યુત-ઇસ્ત્રી 5 A પ્રવાહ લે છે. 30 s માં ઉત્પન્ન ઉષ્મા ગણો."))
add("it7.q1", ("विद्युत धारा द्वारा प्रदत्त ऊर्जा की दर का निर्धारण कैसे किया जाता है?", "વિદ્યુતપ્રવાહ દ્વારા અપાતી ઊર્જાનો દર કેવી રીતે નક્કી થાય છે?"),
    {0: ("विद्युत शक्ति द्वारा।", "વિદ્યુતપાવર દ્વારા."), 1: ("{0}: विभवांतर और धारा का गुणनफल।", "{0}: સ્થિતિમાનના તફાવત અને પ્રવાહનો ગુણાકાર.")})
add("it7.q2", ("कोई विद्युत मोटर 220 V के विद्युत स्रोत से 5.0 A विद्युत धारा लेता है। मोटर की शक्ति निर्धारित कीजिए तथा 2 घंटे में मोटर द्वारा उपभुक्त ऊर्जा परिकलित कीजिए।", "એક વિદ્યુત-મોટર 220 V ના સ્રોતમાંથી 5.0 A પ્રવાહ લે છે. મોટરનો પાવર નક્કી કરો અને 2 કલાકમાં મોટર દ્વારા વપરાતી ઊર્જા ગણો."),
    {1: ("ऊर्जा {0} kW {1} h {2} kWh {3} J", "ઊર્જા {0} kW {1} h {2} kWh {3} J")})

# Exercises
mc("ex.q1", ("R प्रतिरोध के किसी तार के टुकड़े को पाँच बराबर भागों में काटा जाता है। इन टुकड़ों को फिर पार्श्वक्रम में संयोजित कर देते हैं। यदि संयोजन का तुल्य प्रतिरोध R′ है, तो R/R′ अनुपात का मान है –", "R અવરોધના તારના ટુકડાને પાંચ સરખા ભાગમાં કાપવામાં આવે છે. આ ટુકડાઓને પછી સમાંતર જોડવામાં આવે છે. જો જોડાણનો સમતુલ્ય અવરોધ R′ હોય, તો R/R′ ગુણોત્તર છે –"),
   ("प्रत्येक भाग का प्रतिरोध R/5 है; ऐसे पाँच पार्श्वक्रम में R′ = R/25 देते हैं, अतः R/R′ = 25।", "દરેક ભાગનો અવરોધ R/5 છે; આવા પાંચ સમાંતર R′ = R/25 આપે છે, તેથી R/R′ = 25."),
   {"1/25": (("1/25", "1/25"), ("वह R′/R है।", "તે R′/R છે.")), "1/5": (("1/5", "1/5"), ("प्रत्येक भाग R/5 है; पार्श्वक्रम में वे R/25 देते हैं।", "દરેક ભાગ R/5 છે; સમાંતરમાં તે R/25 આપે છે.")),
    "5": (("5", "5"), ("प्रत्येक भाग R/5 है, पर पाँच पार्श्वक्रम में R/25 देते हैं।", "દરેક ભાગ R/5 છે, પણ પાંચ સમાંતર R/25 આપે છે.")), "25": (("25", "25"), OK)})
mc("ex.q2", ("निम्नलिखित में से कौन-सा पद विद्युत परिपथ में विद्युत शक्ति को निरूपित नहीं करता?", "નીચેનામાંથી કયું પદ વિદ્યુત-પરિપથમાં વિદ્યુતપાવર દર્શાવતું નથી?"), ("P = VI = I²R = V²/R; IR² शक्ति नहीं है।", "P = VI = I²R = V²/R; IR² પાવર નથી."),
   {"$I^{2}R$": (None, ("I²R शक्ति है।", "I²R પાવર છે.")), "$IR^{2}$": (None, OK), "$VI$": (None, ("VI शक्ति है।", "VI પાવર છે.")), "$\\dfrac{V^{2}}{R}$": (None, ("V²/R शक्ति है।", "V²/R પાવર છે."))})
mc("ex.q3", ("किसी विद्युत बल्ब का अनुमतांक 220 V; 100 W है। जब इसे 110 V पर प्रचालित करते हैं, तब इसके द्वारा उपभुक्त शक्ति कितनी होती है?", "એક વિદ્યુત-બલ્બનું રેટિંગ 220 V; 100 W છે. જ્યારે તેને 110 V પર ચલાવીએ ત્યારે તે કેટલો પાવર વાપરે છે?"),
   ("R = 220²/100 = 484 Ω; 110 V पर P = 110²/484 = 25 W।", "R = 220²/100 = 484 Ω; 110 V પર P = 110²/484 = 25 W."),
   {"100 W": (("100 W", "100 W"), ("वह 220 V पर है।", "તે 220 V પર છે.")), "75 W": (("75 W", "75 W"), ("P = V²/R; V आधा करने पर P एक-चौथाई होता है।", "P = V²/R; V અડધો કરતાં P એક-ચતુર્થાંશ થાય છે.")),
    "50 W": (("50 W", "50 W"), ("शक्ति V² पर निर्भर है, V पर नहीं।", "પાવર V² પર આધાર રાખે છે, V પર નહિ.")), "25 W": (("25 W", "25 W"), OK)})
mc("ex.q4", ("दो चालक तार जिनके पदार्थ, लंबाई तथा व्यास समान हैं, किसी विद्युत परिपथ में पहले श्रेणीक्रम में और फिर पार्श्वक्रम में संयोजित किए जाते हैं। श्रेणीक्रम तथा पार्श्वक्रम संयोजन में उत्पन्न ऊष्माओं का अनुपात क्या होगा?", "સમાન દ્રવ્ય, લંબાઈ અને વ્યાસવાળા બે વાહક તાર એક જ સ્થિતિમાનના તફાવત સાથે પહેલાં શ્રેણીમાં અને પછી સમાંતર જોડાય છે. શ્રેણી અને સમાંતર જોડાણમાં ઉત્પન્ન ઉષ્માનો ગુણોત્તર શો હશે?"),
   ("श्रेणीक्रम 2R, पार्श्वक्रम R/2; समान V पर H = V²t/R, अतः अनुपात (1/2R) : (2/R) = 1 : 4।", "શ્રેણી 2R, સમાંતર R/2; સમાન V પર H = V²t/R, તેથી ગુણોત્તર (1/2R) : (2/R) = 1 : 4."),
   {"1:2": (("1:2", "1:2"), ("श्रेणीक्रम 2R, पार्श्वक्रम R/2: अनुपात 1 : 4 है।", "શ્રેણી 2R, સમાંતર R/2: ગુણોત્તર 1 : 4 છે.")), "2:1": (("2:1", "2:1"), ("श्रेणीक्रम में कम ऊष्मा उत्पन्न होती है।", "શ્રેણીમાં ઓછી ઉષ્મા ઉત્પન્ન થાય છે.")),
    "1:4": (("1:4", "1:4"), OK), "4:1": (("4:1", "4:1"), ("वह पार्श्वक्रम से श्रेणीक्रम का अनुपात है।", "તે સમાંતરથી શ્રેણીનો ગુણોત્તર છે."))})
add("ex.q5", ("किसी विद्युत परिपथ में दो बिंदुओं के बीच विभवांतर मापने के लिए वोल्टमीटर को किस प्रकार संयोजित किया जाता है?", "વિદ્યુત-પરિપથમાં બે બિંદુઓ વચ્ચે સ્થિતિમાનનો તફાવત માપવા વૉલ્ટમીટરને કેવી રીતે જોડાય છે?"),
    {0: ("वोल्टमीटर को दोनों बिंदुओं के बीच पार्श्वक्रम में जोड़ा जाता है।", "વૉલ્ટમીટરને બંને બિંદુઓ વચ્ચે સમાંતર જોડાય છે."), 1: ("इसका धन टर्मिनल उच्च विभव वाले बिंदु (सेल के धन टर्मिनल की ओर) से जुड़ता है।", "તેનું ધન ટર્મિનલ ઊંચા સ્થિતિમાનવાળા બિંદુ (કોષના ધન ટર્મિનલ તરફ) સાથે જોડાય છે.")})
add("ex.q6", ("किसी ताँबे के तार का व्यास 0.5 mm तथा प्रतिरोधकता 1.6 × 10⁻⁸ Ω m है। 10 Ω प्रतिरोध का प्रतिरोधक बनाने के लिए कितने लंबे तार की आवश्यकता होगी? यदि इससे दोगुने व्यास का तार लें तो प्रतिरोध में क्या अंतर आएगा?", "તાંબાના તારનો વ્યાસ 0.5 mm અને અવરોધકતા 1.6 × 10⁻⁸ Ω m છે. 10 Ω નો અવરોધક બનાવવા કેટલો લાંબો તાર જોઈએ? જો તેનાથી બમણા વ્યાસનો તાર લઈએ તો અવરોધમાં શો ફેરફાર થાય?"),
    {2: ("व्यास दुगुना करने पर क्षेत्रफल 4 गुना हो जाता है, इसलिए प्रतिरोध एक-चौथाई: 2.5 Ω (यह 7.5 Ω घट जाता है)।", "વ્યાસ બમણો કરતાં ક્ષેત્રફળ 4 ગણું થાય છે, તેથી અવરોધ એક-ચતુર્થાંશ: 2.5 Ω (તે 7.5 Ω ઘટે છે).")})
add("ex.q7", ("किसी प्रतिरोधक में प्रवाहित धारा I तथा उसके सिरों के बीच विभवांतर V के मान नीचे दिए गए हैं (I ऐम्पियर में : V वोल्ट में): 0.5 : 1.6, 1.0 : 3.4, 2.0 : 6.7, 3.0 : 10.2, 4.0 : 13.2। V तथा I के बीच ग्राफ़ खींचकर प्रतिरोधक का प्रतिरोध ज्ञात कीजिए।",
              "કોઈ અવરોધકમાંથી વહેતો પ્રવાહ I અને તેના છેડા વચ્ચેનો સ્થિતિમાનનો તફાવત V નીચે આપ્યા છે (I ઍમ્પિયરમાં : V વૉલ્ટમાં): 0.5 : 1.6, 1.0 : 3.4, 2.0 : 6.7, 3.0 : 10.2, 4.0 : 13.2. V અને I વચ્ચે આલેખ દોરીને અવરોધકનો અવરોધ શોધો."),
    {0: ("x-अक्ष पर I और y-अक्ष पर V लेकर आलेखित कीजिए: बिंदु मूल बिंदु से जाने वाली सरल रेखा के निकट हैं।", "x-અક્ષ પર I અને y-અક્ષ પર V લઈ આલેખ દોરો: બિંદુઓ ઊગમબિંદુમાંથી પસાર થતી સુરેખાની નજીક છે."), 1: ("रेखा की ढाल {0} Ω", "રેખાનો ઢાળ {0} Ω"), 2: ("प्रतिरोधक का प्रतिरोध लगभग 3.4 Ω है।", "અવરોધકનો અવરોધ આશરે 3.4 Ω છે.")})
add("ex.q8", ("किसी अज्ञात प्रतिरोध के प्रतिरोधक के सिरों से 12 V की बैटरी को संयोजित करने पर परिपथ में 2.5 mA विद्युत धारा प्रवाहित होती है। प्रतिरोधक का प्रतिरोध परिकलित कीजिए।", "અજ્ઞાત અવરોધના અવરોધકના છેડે 12 V ની બૅટરી જોડતાં પરિપથમાં 2.5 mA પ્રવાહ વહે છે. અવરોધકનો અવરોધ ગણો."))
add("ex.q9", ("9 V की किसी बैटरी को 0.2 Ω, 0.3 Ω, 0.4 Ω, 0.5 Ω तथा 12 Ω के प्रतिरोधकों के साथ श्रेणीक्रम में संयोजित किया गया है। 12 Ω के प्रतिरोधक से कितनी विद्युत धारा प्रवाहित होगी?", "9 V ની બૅટરીને 0.2 Ω, 0.3 Ω, 0.4 Ω, 0.5 Ω અને 12 Ω ના અવરોધકો સાથે શ્રેણીમાં જોડી છે. 12 Ω ના અવરોધકમાંથી કેટલો પ્રવાહ વહેશે?"),
    {1: ("{0} A; श्रेणीक्रम में 12 Ω के प्रतिरोधक से भी यही धारा बहती है।", "{0} A; શ્રેણીમાં 12 Ω ના અવરોધકમાંથી પણ આ જ પ્રવાહ વહે છે.")})
add("ex.q10", ("176 Ω प्रतिरोध के कितने प्रतिरोधकों को पार्श्वक्रम में संयोजित करें कि 220 V के विद्युत स्रोत से संयोजन से 5 A विद्युत धारा प्रवाहित हो?", "176 Ω ના કેટલા અવરોધકો સમાંતર જોડવા કે 220 V ના સ્રોતમાંથી 5 A પ્રવાહ વહે?"),
    {0: ("आवश्यक प्रतिरोध {0} Ω", "જરૂરી અવરોધ {0} Ω"), 1: ("n समान प्रतिरोधक पार्श्वक्रम में देते हैं {0}, अतः {1}", "n સરખા અવરોધકો સમાંતર આપે છે {0}, તેથી {1}")})
add("ex.q11", ("यह दर्शाइए कि आप 6 Ω प्रतिरोध के तीन प्रतिरोधकों को किस प्रकार संयोजित करेंगे कि प्राप्त संयोजन का प्रतिरोध (i) 9 Ω, (ii) 4 Ω हो।", "દર્શાવો કે 6 Ω ના ત્રણ અવરોધકોને કેવી રીતે જોડશો કે જોડાણનો અવરોધ (i) 9 Ω, (ii) 4 Ω થાય."),
    {0: ("(i) दो पार्श्वक्रम में (3 Ω), तीसरे के साथ श्रेणीक्रम में: {0} Ω", "(i) બે સમાંતર (3 Ω), ત્રીજા સાથે શ્રેણીમાં: {0} Ω"), 1: ("(ii) दो श्रेणीक्रम में (12 Ω), तीसरे के साथ पार्श्वक्रम में: {0} Ω", "(ii) બે શ્રેણીમાં (12 Ω), ત્રીજા સાથે સમાંતર: {0} Ω")})
add("ex.q12", ("220 V की विद्युत लाइन पर उपयोग किए जाने वाले बहुत से बल्बों का अनुमतांक 10 W है। यदि 220 V लाइन से अनुमत अधिकतम विद्युत धारा 5 A है तो इस लाइन के दो तारों के बीच कितने बल्ब पार्श्वक्रम में संयोजित किए जा सकते हैं?", "220 V ની લાઇન પર વપરાતા ઘણા બલ્બનું રેટિંગ 10 W છે. જો 220 V ની લાઇનમાંથી મહત્તમ માન્ય પ્રવાહ 5 A હોય, તો લાઇનના બે તાર વચ્ચે કેટલા બલ્બ સમાંતર જોડી શકાય?"),
    {0: ("एक बल्ब में धारा {0} A", "એક બલ્બમાં પ્રવાહ {0} A"), 1: ("बल्बों की संख्या {0}", "બલ્બની સંખ્યા {0}")})
add("ex.q13", ("किसी विद्युत भट्टी की तप्त प्लेट दो प्रतिरोधक कुंडलियों A तथा B की बनी है जिनमें प्रत्येक का प्रतिरोध 24 Ω है तथा इन्हें पृथक्-पृथक्, श्रेणीक्रम में अथवा पार्श्वक्रम में संयोजित करके उपयोग किया जा सकता है। यदि यह भट्टी 220 V विद्युत स्रोत से संयोजित की जाती है तो तीनों प्रकरणों में कितनी विद्युत धाराएँ प्रवाहित होंगी?",
               "વિદ્યુત-ભઠ્ઠીની ગરમ પ્લેટ બે ગૂંચળાં A અને B ની બનેલી છે, દરેકનો અવરોધ 24 Ω છે, અને તેમને અલગ-અલગ, શ્રેણીમાં કે સમાંતર વાપરી શકાય છે. જો ભઠ્ઠી 220 V ના સ્રોત સાથે જોડાય, તો ત્રણેય કિસ્સામાં કેટલો પ્રવાહ વહેશે?"),
    {0: ("पृथक्-पृथक्: {0} A", "અલગ-અલગ: {0} A"), 1: ("श्रेणीक्रम में: {0} Ω, {1} A", "શ્રેણીમાં: {0} Ω, {1} A"), 2: ("पार्श्वक्रम में: {0} Ω, {1} A", "સમાંતરમાં: {0} Ω, {1} A")})
add("ex.q14", ("निम्नलिखित परिपथों में प्रत्येक में 2 Ω प्रतिरोधक द्वारा उपभुक्त शक्तियों की तुलना कीजिए: (i) 6 V की बैटरी से संयोजित 1 Ω तथा 2 Ω श्रेणीक्रम संयोजन, (ii) 4 V बैटरी से संयोजित 12 Ω तथा 2 Ω का पार्श्वक्रम संयोजन।", "નીચેના દરેક પરિપથમાં 2 Ω ના અવરોધક દ્વારા વપરાતા પાવરની સરખામણી કરો: (i) 6 V ની બૅટરી સાથે 1 Ω અને 2 Ω નું શ્રેણી-જોડાણ, (ii) 4 V ની બૅટરી સાથે 12 Ω અને 2 Ω નું સમાંતર જોડાણ."),
    {1: ("(ii) 2 Ω के प्रतिरोधक पर पूरा 4 V है: {0} W", "(ii) 2 Ω ના અવરોધક પર પૂરો 4 V છે: {0} W"), 2: ("2 Ω के प्रतिरोधक द्वारा उपभुक्त शक्ति दोनों परिपथों में समान, 8 W, है।", "2 Ω ના અવરોધક દ્વારા વપરાતો પાવર બંને પરિપથમાં સરખો, 8 W, છે.")})
add("ex.q15", ("दो विद्युत लैंप जिनमें से एक का अनुमतांक 100 W; 220 V तथा दूसरे का 60 W; 220 V है, विद्युत मेंस के साथ पार्श्वक्रम में संयोजित हैं। यदि विद्युत आपूर्ति की वोल्टता 220 V है तो विद्युत मेंस से कितनी धारा ली जाती है?", "બે વિદ્યુત-લૅમ્પ, એકનું રેટિંગ 100 W; 220 V અને બીજાનું 60 W; 220 V, મેઇન્સ સાથે સમાંતર જોડ્યા છે. જો પુરવઠાનો વૉલ્ટેજ 220 V હોય, તો મેઇન્સમાંથી કેટલો પ્રવાહ લેવાય છે?"),
    {0: ("कुल शक्ति {0} W", "કુલ પાવર {0} W")})
add("ex.q16", ("किसमें अधिक विद्युत ऊर्जा उपभुक्त होती है: 250 W का टीवी सेट जो 1 घंटे तक चलाया जाता है अथवा 1200 W का विद्युत टोस्टर जो 10 मिनट के लिए चलाया जाता है?", "શેમાં વધુ વિદ્યુતઊર્જા વપરાય છે: 1 કલાક ચાલતું 250 W નું ટીવી કે 10 મિનિટ ચાલતું 1200 W નું ટોસ્ટર?"),
    {0: ("टीवी: {0} Wh। टोस्टर: {1} Wh", "ટીવી: {0} Wh. ટોસ્ટર: {1} Wh"), 1: ("टीवी सेट अधिक ऊर्जा उपभुक्त करता है।", "ટીવી વધુ ઊર્જા વાપરે છે.")})
add("ex.q17", ("44 Ω प्रतिरोध का कोई विद्युत हीटर विद्युत मेंस से 2 घंटे तक 5 A विद्युत धारा लेता है। हीटर में उत्पन्न ऊष्मा की दर परिकलित कीजिए।", "44 Ω અવરોધનું વિદ્યુત-હીટર મેઇન્સમાંથી 2 કલાક સુધી 5 A પ્રવાહ લે છે. હીટરમાં ઉષ્મા ઉત્પન્ન થવાનો દર ગણો."),
    {1: ("{0} W (हर सेकंड 1100 J ऊष्मा)", "{0} W (દર સેકન્ડે 1100 J ઉષ્મા)")})
add("ex.q18", ("निम्नलिखित की व्याख्या कीजिए।\n\n(a) विद्युत लैंपों के तंतुओं के निर्माण में प्रायः एकमात्र टंगस्टन का ही उपयोग क्यों किया जाता है?\n\n(b) विद्युत तापन युक्तियों जैसे ब्रेड-टोस्टर तथा विद्युत इस्तरी के चालक शुद्ध धातुओं के स्थान पर मिश्रातुओं के क्यों बनाए जाते हैं?\n\n"
               "(c) घरेलू विद्युत परिपथों में श्रेणीक्रम संयोजन का उपयोग क्यों नहीं किया जाता?\n\n(d) किसी तार का प्रतिरोध उसकी अनुप्रस्थ काट के क्षेत्रफल में परिवर्तन के साथ किस प्रकार परिवर्तित होता है?\n\n(e) विद्युत संचारण के लिए प्रायः कॉपर तथा ऐलुमिनियम के तारों का उपयोग क्यों किया जाता है?",
               "નીચેની બાબતો સમજાવો.\n\n(a) વિદ્યુત-લૅમ્પના ફિલામેન્ટ બનાવવા લગભગ ફક્ત ટંગસ્ટન જ કેમ વપરાય છે?\n\n(b) બ્રેડ-ટોસ્ટર અને ઇસ્ત્રી જેવાં ગરમ કરતાં સાધનોના વાહક શુદ્ધ ધાતુને બદલે મિશ્રધાતુના કેમ બનાવાય છે?\n\n"
               "(c) ઘરેલુ પરિપથમાં શ્રેણી-જોડાણ કેમ વપરાતું નથી?\n\n(d) તારનો અવરોધ તેના આડછેદના ક્ષેત્રફળ સાથે કેવી રીતે બદલાય છે?\n\n(e) વીજ-વહન માટે સામાન્ય રીતે તાંબા અને ઍલ્યુમિનિયમના તાર કેમ વપરાય છે?"),
    {0: ("(a) टंगस्टन का गलनांक बहुत उच्च (3380 °C) और प्रतिरोधकता अधिक है, इसलिए वह बिना पिघले श्वेत-तप्त होकर चमक सकता है।", "(a) ટંગસ્ટનનું ગલનબિંદુ ખૂબ ઊંચું (3380 °C) અને અવરોધકતા વધુ છે, તેથી તે પીગળ્યા વિના શ્વેત-તપ્ત થઈ પ્રકાશી શકે છે."),
     1: ("(b) मिश्रातुओं की प्रतिरोधकता अधिक होती है और वे उच्च ताप पर आसानी से उपचयित (दग्ध) नहीं होते।", "(b) મિશ્રધાતુઓની અવરોધકતા વધુ હોય છે અને તે ઊંચા તાપમાને સહેલાઈથી ઑક્સિડાઇઝ (સળગતી) થતી નથી."),
     2: ("(c) श्रेणीक्रम में सभी उपकरण वोल्टता बाँटते हैं, अपनी आवश्यक धारा नहीं ले पाते, और एक के ख़राब होने पर सभी बंद हो जाते हैं; उन्हें स्वतंत्र रूप से चालू-बंद नहीं किया जा सकता।", "(c) શ્રેણીમાં બધાં ઉપકરણો વૉલ્ટેજ વહેંચે છે, પોતાને જોઈતો પ્રવાહ લઈ શકતાં નથી, અને એક બગડે તો બધાં બંધ થઈ જાય છે; તેમને સ્વતંત્ર રીતે ચાલુ-બંધ કરી શકાતાં નથી."),
     3: ("(d) प्रतिरोध अनुप्रस्थ काट के क्षेत्रफल के व्युत्क्रमानुपाती है: मोटे तार का प्रतिरोध कम होता है।", "(d) અવરોધ આડછેદના ક્ષેત્રફળના વ્યસ્ત પ્રમાણમાં છે: જાડા તારનો અવરોધ ઓછો હોય છે."),
     4: ("(e) ताँबे और ऐलुमिनियम की प्रतिरोधकता बहुत कम है, इसलिए तारों में ऊष्मा के रूप में कम ऊर्जा व्यर्थ होती है।", "(e) તાંબા અને ઍલ્યુમિનિયમની અવરોધકતા ખૂબ ઓછી છે, તેથી તારમાં ઉષ્મા સ્વરૂપે ઓછી ઊર્જા વેડફાય છે.")})

