add("gseb2025_32", ("कुछ पदार्थों की प्रतिरोधकता: चाँदी 1.60 × 10⁻⁸ Ω m, ताँबा 1.62 × 10⁻⁸ Ω m, लोहा 10.0 × 10⁻⁸ Ω m, पारा 94.0 × 10⁻⁸ Ω m, मैंगनीज़ 1.84 × 10⁻⁶ Ω m।\n\n(a) लोहे और पारे में कौन अच्छा चालक है?\n\n(b) कौन-सा पदार्थ सर्वश्रेष्ठ चालक है?", "કેટલાક પદાર્થોની અવરોધકતા: ચાંદી 1.60 × 10⁻⁸ Ω m, તાંબું 1.62 × 10⁻⁸ Ω m, લોખંડ 10.0 × 10⁻⁸ Ω m, પારો 94.0 × 10⁻⁸ Ω m, મૅંગેનીઝ 1.84 × 10⁻⁶ Ω m.\n\n(a) લોખંડ અને પારામાંથી કયું સારું વાહક છે?\n\n(b) કયો પદાર્થ સૌથી સારો વાહક છે?"),
    {0: ("(a) लोहा, क्योंकि उसकी प्रतिरोधकता पारे से कम है।", "(a) લોખંડ, કારણ કે તેની અવરોધકતા પારા કરતાં ઓછી છે."), 1: ("(b) चाँदी, जिसकी प्रतिरोधकता सबसे कम है।", "(b) ચાંદી, જેની અવરોધકતા સૌથી ઓછી છે.")})
add("gseb2024_32", ("12 V विभवांतर वाले दो बिंदुओं के बीच 2 C आवेश को ले जाने में कितना कार्य होता है?", "12 V સ્થિતિમાનના તફાવતવાળાં બે બિંદુઓ વચ્ચે 2 C વિદ્યુતભાર લઈ જવામાં કેટલું કાર્ય થાય છે?"))
add("gseb2024_46", ("विद्युत धारा के तापीय प्रभाव के व्यावहारिक अनुप्रयोग उदाहरण सहित समझाइए।", "વિદ્યુતપ્રવાહની ઉષ્મીય અસરના વ્યવહારુ ઉપયોગો ઉદાહરણ સાથે સમજાવો."),
    {0: ("तापन उपकरण: विद्युत इस्त्री, टोस्टर, ओवन, केतली और रूम हीटर में नाइक्रोम जैसे मिश्रातु की कुंडलियाँ धारा बहने पर गर्म होती हैं।", "ગરમ કરતાં ઉપકરણો: વિદ્યુત-ઇસ્ત્રી, ટોસ્ટર, ઓવન, કીટલી અને રૂમ-હીટરમાં નાઇક્રોમ જેવી મિશ્રધાતુનાં ગૂંચળાં પ્રવાહ વહેતાં ગરમ થાય છે."),
     1: ("विद्युत बल्ब: पतला टंगस्टन तंतु इतना गर्म होता है कि चमककर प्रकाश देता है; बल्ब में नाइट्रोजन और आर्गन भरी होती है।", "વિદ્યુત-બલ્બ: પાતળો ટંગસ્ટન ફિલામેન્ટ એટલો ગરમ થાય છે કે પ્રકાશીને પ્રકાશ આપે છે; બલ્બમાં નાઇટ્રોજન અને આર્ગન ભરેલાં હોય છે."),
     2: ("विद्युत फ़्यूज़: श्रेणीक्रम में जुड़ा कम गलनांक वाला तार धारा बहुत अधिक होने पर पिघलकर परिपथ तोड़ देता है और उपकरणों की रक्षा करता है।", "વિદ્યુત-ફ્યૂઝ: શ્રેણીમાં જોડેલો ઓછા ગલનબિંદુવાળો તાર પ્રવાહ ખૂબ વધે ત્યારે પીગળીને પરિપથ તોડી નાખે છે અને ઉપકરણોનું રક્ષણ કરે છે.")})

